mapper.sql:
WHERE r.deleted_at IS NULL


    AND r.needs_location = 0
    AND r.longitude BETWEEN #{query.west} AND #{query.east}
    AND r.latitude BETWEEN #{query.south} AND #{query.north}

AND r.category_code = #{query.category}

AND r.restaurant_type = #{query.restaurantType}
AND r.supports_dine_in = TRUE
AND r.supports_delivery = TRUE
AND r.business_status = 'OPERATING'


    AND r.price_kind != 'UNKNOWN' AND r.price_per_person <= #{query.maxPrice}


    AND () <= #{query.maxDistanceMeters}


    AND (r.name LIKE #{query.keywordPattern} ESCAPE '!'
        OR r.address LIKE #{query.keywordPattern} ESCAPE '!'
        OR c.name LIKE #{query.keywordPattern} ESCAPE '!'
        OR EXISTS (SELECT 1 FROM restaurant_tags t WHERE t.restaurant_id = r.id
            AND t.tag LIKE #{query.keywordPattern} ESCAPE '!'))
